from pathlib import Path
import json,re,csv
root=Path(__file__).resolve().parent
rows=json.loads((root/'batteries.json').read_text(encoding='utf-8'))
screen=(root.parent/'display-protocol-filter-20261009/template.html').read_text(encoding='utf-8')
css=re.search(r'<style>(.*?)</style>',screen,re.S).group(1)
css+=' .battery-filters{grid-template-columns:repeat(5,minmax(110px,1fr))}.battery-filters label{grid-column:auto!important;display:block!important}.diagram{padding:16px;overflow:auto}.diagram svg{max-width:100%;height:auto} .calc{color:#536377;font-size:12px}@media(max-width:700px){.battery-filters{grid-template-columns:1fr 1fr}}'
css+=' @media(max-width:700px){.page-head{flex-wrap:wrap}.page-head .primary{margin-top:4px}}'
body='''<header class="shell"><div class="brand">TEAMO <span style="font-size:12px;font-weight:400;margin-left:20px">硬件选型工作台</span></div><div class="shell-note">电源系统 · 2026.10.09</div></header><div class="workspace"><aside><div class="nav-title">HARDWARE WORKSPACE</div><a class="nav-link" href="../display-protocol-filter-20261009/index.html">显示屏物料库</a><a class="nav-link current" href="index.html">电池物料库</a><a class="nav-link" href="../system-layout-20261009/index.html">整机选型与排布</a><a class="nav-link" href="../rv1106-board-identification-20261009/index.html">主控开发平台</a></aside><main><div class="breadcrumb">硬件研发 / 电源系统 / 电池选型</div><div class="page-head"><div><h1>电池物料库</h1><p class="subtitle">先核包络与放电能力，再比较容量、续航和供货。</p></div><a class="primary" href="batteries.csv" download>导出清单 ↓</a></div><section class="metrics"><div class="metric"><div class="metric-label">真实型号记录</div><div class="metric-value" id="total"></div></div><div class="metric"><div class="metric-label">尺寸 / 容量初筛保留</div><div class="metric-value blue" id="pass"></div></div><div class="metric"><div class="metric-label">当前工况所需电池电流</div><div class="metric-value" id="current"></div><div class="metric-foot">低电压端平均值；峰值另测</div></div><div class="metric"><div class="metric-label">厂家产品图覆盖</div><div class="metric-value" id="photos"></div></div></section><div class="notice">开发板是验证平台，产品自研 PCB。容量不能证明能带动 RV1106＋4G＋功放；保护过流阈值、充电电流、峰值电流不能替代连续放电能力。以下为讨论输入，不是最终供电设计。</div><section class="panel"><div class="panel-head"><h2>结构条件与续航假设</h2><span>可调整 / 未实测</span></div><div class="filters battery-filters"><label>最小容量 mAh<input id="cap" type="number" value="1000" min="1"></label><label>包体短边上限 mm<input id="width" type="number" value="50" min="1"></label><label>包体长边上限 mm<input id="height" type="number" value="70" min="1"></label><label>包体厚度上限 mm<input id="depth" type="number" value="10" min="1"></label><label>形态<select id="form"><option>全部</option><option>软包</option><option>圆柱包</option><option>裸圆柱</option></select></label><label>负载平均功率 W<input id="power" type="number" value="5" min="0.1" step="0.1"></label><label>转换效率 %<input id="eff" type="number" value="85" min="1" max="100"></label><label>可用能量比例 %<input id="usable" type="number" value="80" min="1" max="100"></label><label>低电压计算点 V<input id="low" type="number" value="3.3" min="1" step="0.1"></label><label>目标续航 h<input id="hours" type="number" value="1" min="0.1" step="0.1"></label></div><p class="image-meta">包体尺寸未计线材、插头、支架、软包膨胀余量。80%可用能量是待验证预算，不能替代电芯放电曲线、老化与温度测试。</p></section><section class="panel"><div class="toolbar"><input id="search" class="search" placeholder="搜索型号或厂家" aria-label="搜索电池"><label><input id="only" type="checkbox"> 只看尺寸 / 容量初筛保留</label><button class="secondary" id="reset">重置条件</button></div><div class="summary" id="summary"></div><div class="table"><table><thead><tr><th>型号 / 厂家图</th><th>容量 / 标称电压</th><th>包体W×H×T mm</th><th>放电 / PCM / NTC</th><th>估算续航</th><th>初筛 / 电气状态</th><th>价格 / 供货 / 缺项</th></tr></thead><tbody id="rows"></tbody></table></div></section><section class="panel"><details class="evidence" open><summary>电池与结构、供电的讨论结论</summary><p>紧凑软包路线优先询价 2000–2500mAh、带PCM与NTC、连续电流按整机峰值预算定制的成品包；现有参考型号尚未证明全负载满足。薄型1100mAh包可做低功耗对照，不直接推荐为整机主电池。</p><p>圆柱路线优先对照单节18650成品包与1S2P成品包：厚度约18mm起，换取刚性电芯与容量，但保护板、线材、支架仍占空间。裸P28A是电芯能力参考，不能直接接入开发板。</p><p>若未确认断电使用场景，第一版台架可外接USB供电；电池供电、边充边用、充电温控与4G瞬态作为独立验证项。</p><p><a href="电池选型与功耗结构输入.md">详细依据 / 问题清单</a> · <a href="../电池国内厂家复核_20261009.md">国内厂家复核</a> · <a href="../system-layout-20261009/index.html">整机排布与尺寸推导</a></p></details></section><footer class="footnote">所有零售价为USD公开参考；不是国内含税BOM价。记录日期2026-10-09。</footer></main></div>'''
script=r'''
const data=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),esc=x=>String(x??'待核').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){const keys=['cap','width','height','depth','power','eff','usable','low','hours'],n=Object.fromEntries(keys.map(k=>[k,Number($(k).value)]));if(keys.some(k=>!$(k).value||n[k]<=0)||n.eff>100||n.usable>100){$('summary').textContent='请输入有效的正数阈值；效率和可用比例不超过100%。';$('rows').innerHTML='';return;}const req=n.power/(n.eff/100*n.low);let pass=0,shown=0;const list=[];for(const p of data){let out=[];if(p.capacity<n.cap)out.push('容量不足');if(!p.dims)out.push('成品尺寸未知');else if(p.dims[0]>n.width||p.dims[1]>n.height||p.dims[2]>n.depth)out.push('包体轴长超限');if($('form').value!=='全部'&&p.form!==$('form').value)out.push('形态不符');if($('search').value&&!p.model.toLowerCase().includes($('search').value.toLowerCase()))out.push('搜索不符');const ok=!out.length;if(ok)pass++;if($('only').checked&&!ok)continue;shown++;const runtime=p.capacity/1000*p.voltage*(n.eff/100)*(n.usable/100)/n.power;const electrical=p.continuous==null?'连续放电待核':p.continuous<req?'该参考电流低于当前平均需求':'电芯/包额定参考覆盖平均值，峰值和线材仍待核';list.push(`<tr><td><b>${esc(p.id)} ${esc(p.model)}</b><details class="row-detail"><summary>${p.photo?'查看厂家图':'图片状态'}</summary>${p.photo?`<a href="${esc(p.photo)}" target="_blank"><img class="pic" src="${esc(p.photo)}" alt="${esc(p.model)}厂家产品图"></a>`:''}<p>${esc(p.photo_note)}</p></details><a href="${esc(p.url)}" target="_blank" rel="noopener">官方资料</a></td><td>${p.capacity}mAh<br>${p.voltage}V<br>${(p.capacity/1000*p.voltage).toFixed(2)}Wh</td><td>${p.dims?p.dims.join('×'):'未知'}<br>${esc(p.dimension_status)}${p.tolerance?`<br>轴向公差/最大值规则 ${p.tolerance.join('/')}mm`:''}</td><td>${p.continuous==null?'连续值待核':p.continuous+'A 参考连续/建议值'}<br>PCM ${p.pcm===true?'有':p.pcm===false?'裸芯无':'待核'} / NTC ${p.ntc===true?'有':p.ntc===false?'无':'待核'}</td><td>${runtime.toFixed(2)}h<br>目标${n.hours}h：${runtime>=n.hours?'能量预算覆盖':'能量不足'}<br><span class="small">估算，非实测</span></td><td>${ok?'尺寸/容量初筛保留':out.join('；')}<br><span class="pending">${electrical}</span></td><td>${esc(p.price)}<br>${esc(p.domestic)}<details class="row-detail"><summary>型号缺项</summary>${esc(p.notes)}</details></td></tr>`)}$('total').textContent=data.length;$('pass').textContent=pass;$('current').textContent=req.toFixed(2)+'A';$('photos').textContent=data.filter(p=>p.photo).length+'/'+data.length;$('rows').innerHTML=list.join('');$('summary').textContent=`${data.length}条型号 · ${pass}条尺寸/容量初筛保留 · 当前显示${shown}条。估算续航=容量×标称电压×效率×可用比例÷平均功率。峰值功率与低压截止需实测。`;window.batteryReview={pass,shown,req};}
for(const e of document.querySelectorAll('input,select'))e.addEventListener('input',render);$('reset').onclick=()=>{for(const [k,v] of Object.entries({cap:1000,width:50,height:70,depth:10,power:5,eff:85,usable:80,low:3.3,hours:1,form:'全部',search:''}))$(k).value=v;$('only').checked=false;render()};render();
'''
html='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>电池物料库 · TEAMO</title><style>'+css+'</style>'+body+'<script type="application/json" id="data">'+json.dumps(rows,ensure_ascii=False).replace('<','\\u003c')+'</script><script>'+script+'</script></html>'
(root/'index.html').write_text(html,encoding='utf-8')
with (root/'batteries.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.writer(f);w.writerow(['ID','型号','容量mAh','电压V','包体WHT','连续参考A','PCM','NTC','价格','来源','缺项'])
 for r in rows:w.writerow([r['id'],r['model'],r['capacity'],r['voltage'],r['dims'],r['continuous'],r['pcm'],r['ntc'],r['price'],r['url'],r['notes']])
print('Built battery catalog',len(rows))
